create table public.cp_business_suppliers(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),name text not null,contact text not null default '',phone text not null default '',email text not null default '',rfc text not null default '',address text not null default '',terms text not null default '',notes text not null default '',active boolean not null default true,revision integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.cp_purchase_orders(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),supplier_id uuid not null references public.cp_business_suppliers(id),warehouse_id uuid not null references public.almacenes(id),supplier_name text not null,reference text not null default '',expected_on date,notes text not null default '',items jsonb not null,subtotal numeric(14,2) not null,discount numeric(14,2) not null default 0,tax numeric not null default 0,total numeric(14,2) not null,status text not null default 'borrador' check(status in ('borrador','ordenada','recibida','cancelada')),received_at timestamptz,revision integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.cp_finance_accounts(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),kind text not null check(kind in ('cobrar','pagar')),party text not null,phone text not null default '',concept text not null,reference text not null default '',amount numeric(14,2) not null check(amount>0),due_on date not null,sale_id text references public.cp_sales(id),purchase_id uuid references public.cp_purchase_orders(id),status text not null default 'abierta' check(status in ('abierta','cancelada')),created_at timestamptz not null default now(),revision integer not null default 0);
create unique index cp_finance_sale_unique on public.cp_finance_accounts(user_id,sale_id) where sale_id is not null and status='abierta';
create unique index cp_finance_purchase_unique on public.cp_finance_accounts(user_id,purchase_id) where purchase_id is not null and status='abierta';
create table public.cp_finance_payments(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),account_id uuid not null references public.cp_finance_accounts(id),amount numeric(14,2) not null check(amount>0),paid_on date not null,method text not null,reference text not null default '',expense_id uuid,voided boolean not null default false,void_reason text,voided_at timestamptz,created_at timestamptz not null default now());
create table public.cp_service_cases(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),subject text not null,customer text not null,phone text not null default '',sale_id text references public.cp_sales(id),category text not null default 'Soporte',priority text not null default 'normal' check(priority in ('normal','alta','urgente')),status text not null default 'abierto' check(status in ('abierto','en proceso','en espera','resuelto')),owner_name text not null default '',due_on date,description text not null default '',resolution text not null default '',resolved_at timestamptz,revision integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.cp_case_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),case_id uuid not null references public.cp_service_cases(id),message text not null,created_at timestamptz not null default now());
create table public.cp_business_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),month date not null check(extract(day from month)=1),sales_goal numeric(14,2) not null check(sales_goal>=0),expense_budget numeric(14,2) not null check(expense_budget>=0),notes text not null default '',updated_at timestamptz not null default now(),unique(user_id,month));
create table public.cp_business_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),request_id uuid not null,payload_hash text not null,result jsonb not null,created_at timestamptz not null default now(),unique(user_id,request_id));
create table public.cp_business_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),action text not null,entity_id uuid,summary text not null,created_at timestamptz not null default now());
do $$declare t text;begin
 foreach t in array array['cp_business_suppliers','cp_purchase_orders','cp_finance_accounts','cp_finance_payments','cp_service_cases','cp_case_events','cp_business_goals','cp_business_requests','cp_business_events'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy %I on public.%I for select to authenticated using(user_id=(select auth.uid()))',t||'_read',t);
 execute format('create index %I on public.%I(user_id,id)',t||'_owner_idx',t);
 end loop;end $$;
create index cp_finance_payments_account_idx on public.cp_finance_payments(account_id);
create index cp_finance_payments_expense_idx on public.cp_finance_payments(expense_id) where expense_id is not null;
create index cp_case_events_case_idx on public.cp_case_events(case_id,created_at);
